export function localDay(date=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
export function dailyReading(signId,date=localDay()){const sign=signs.find(s=>s.id===signId)||signs[0];let hash=2166136261;for(const ch of date+sign.id)hash=Math.imul(hash^ch.charCodeAt(0),16777619)>>>0;return{sign,date,focus:dailyPrompts.focus[hash%6],connection:dailyPrompts.connection[(hash>>>4)%6],care:dailyPrompts.care[(hash>>>9)%6]}}
export function randomIndex(max){if(!Number.isInteger(max)||max<1)throw new Error('Invalid random range');const n=new Uint32Array(1),limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(n)}while(n[0]>=limit);return n[0]%max}
export function drawTarot(count=1,reverse=false){const pool=[...tarotCards];if(count!==1&&count!==3)throw new Error('Choose one or three cards');return Array.from({length:count},()=>({card:pool.splice(randomIndex(pool.length),1)[0],reversed:reverse&&randomIndex(4)===0}))}
